"""Pure selector regression, no PA imports/live API/state construction."""
from dataclasses import FrozenInstanceError,replace
import json,unittest
from pathlib import Path
from systemic_activation_bindings import BINDING,fingerprint,selectors,validate_target

class Selectors(unittest.TestCase):
 def test_pr_changes_only_github_selector(self):
  older,newer=selectors(524),selectors(525)
  self.assertEqual([k for k in older if older[k]!=newer[k]],['github_pr'])
  self.assertEqual(newer['backup_job'],'/api/fleet/dispatch-jobs/c5a697e5-c62b-4d76-9523-def2f5fc852d')
 def test_bad_backup_uuid_is_rejected(self):
  wrong=replace(BINDING,backup_dispatch='c5a697e5-c62b-4d76-9524-def2f5fc852d')
  with self.assertRaises(AssertionError):selectors(525,wrong)
 def test_bindings_frozen_and_target_bound_to_session(self):
  with self.assertRaises(FrozenInstanceError):BINDING.fence=291
  valid={'binding_sha256':fingerprint(),'repository':'petersky/pa','head':'a'*40,'pr':525,'previous_handoff':'existing','previous_loaded':{'source_revision':'b'*40},'merge':'c'*40}
  self.assertEqual(validate_target(valid),selectors(525))
  with self.assertRaises(AssertionError):validate_target({**valid,'binding_sha256':'0'*64})

if __name__=='__main__':
 result=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(Selectors))
 out={'binding_sha256':fingerprint(),'run':result.testsRun,'failures':len(result.failures),'errors':len(result.errors),'scope':'Pure session selector tests; no PA imports/state/live calls. Wrong historical9524backupUUID rejected; PRnumber changes no session selectors.'}
 p=Path('.dev/systemic-activation-bindings-tests.json');assert not p.exists();p.write_text(json.dumps(out,indent=2)+'\n')
 raise SystemExit(0 if result.wasSuccessful() else 1)
